mapper.select:
SELECT id, task_type, document_id, document_line_id, source_location_id, target_location_id, planned_qty,
       completed_qty, state, assignee_id, claim_epoch, version
FROM inbound_task
WHERE enterprise_id = #{enterpriseId}
  AND warehouse_id = #{warehouseId}
  AND task_type = #{taskType}

    AND id > #{cursor}

ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE inbound_task
SET assignee_id = #{workerId},
    claim_epoch = #{epoch},
    version = version + 1,
    updated_at = #{now}
WHERE enterprise_id = #{enterpriseId}
  AND warehouse_id = #{warehouseId}
  AND id = #{taskId}
  AND version = #{expectedVersion}
